class Solution {
  public int nthSuperUglyNumber(int n, int[] primes) {
    long[] ugly = new long[n];
    int[] idx = new int[primes.length];
    long[] next = new long[primes.length];
    for (int j = 0; j < primes.length; j++) next[j] = primes[j];
    ugly[0] = 1;
    for (int i = 1; i < n; i++) {
      long min = Long.MAX_VALUE;
      for (long v : next) min = Math.min(min, v);
      ugly[i] = min;
      for (int j = 0; j < primes.length; j++) if (next[j] == min) next[j] = ugly[++idx[j]] * primes[j];
    }
    return (int) ugly[n - 1];
  }
}
